def get_quiz(exercise_id: str, part_index: int) -> dict:
    import copy
    try:
        question, options, answer, explanation = QUIZZES[exercise_id][part_index]
    except (KeyError, IndexError) as error:
        raise ValueError("No quiz question exists for this exercise part.") from error
    return copy.deepcopy({"question": question, "options": options,
                          "answer": answer, "explanation": explanation})
